      selectedRows: {},
      labelBulkSelecting: false,
      detail: null,
      detailOrderItems: [],
      detailOrderItemsOrderId: null,
      detailPayments: [],
      detailPaymentsOrderId: null,
      detailPaymentsLoading: false,
      detailItemsLoading: false,
      detailItemForm: null,
      detailParentOrder: null,
      detailReturnsToParentOrder: false,
      copiedOrderLinkId: null,
      copiedDeepLinkKey: '',
      itemPublicLinks: {},
      itemPublicLinkLoading: {},
      itemPublicLinkErrors: {},
      copiedPublicItemId: null,
      copiedLayoutLinkId: null,
      layoutUploading: {},
